mapper.select:
SELECT a.id, a.device_id, a.object_type, a.alarm_type, a.alarm_level, a.alarm_value::text AS alarm_value_json, a.status, a.occur_time, a.close_time, a.created_at FROM t_alarm AS a
AND a.device_id = #{deviceId}
AND a.object_type = #{objectType}
AND a.alarm_type = #{alarmType}
AND a.alarm_level = #{alarmLevel}
AND a.status = #{status}
ORDER BY a.occur_time DESC, a.id DESC

mapper.delete:
DELETE FROM t_alarm
WHERE object_type = #{objectType}
  AND device_id = #{deviceId}
